export async function lookupDictionary(word) {
    const clean = word.toLowerCase().replace(/[^a-z\s-]/g, "").trim().replace(/\s+/g, "-");
    if (!clean)
        return [];
    const key = clean.replace(/-/g, " ");
    const data = WORD_DATA[key];
    if (!data) {
        const fuzzy = Object.keys(WORD_DATA).find(k => k.includes(key) || key.includes(k));
        if (!fuzzy)
            return [];
        const d = WORD_DATA[fuzzy];
        return [{ word: fuzzy, definition: d.def, partOfSpeech: d.pos, example: d.ex, source: "local-dictionary" }];
    }
    return [{ word: key, definition: data.def, partOfSpeech: data.pos, example: data.ex, source: "local-dictionary" }];
}
export async function lookupThesaurus(word) {
    const clean = word.toLowerCase().replace(/[^a-z\s-]/g, "").trim().replace(/\s+/g, "-");
    const empty = { word: clean.replace(/-/g, " "), synonyms: [], antonyms: [], source: "local-thesaurus" };
    if (!clean)
        return empty;
    const key = clean.replace(/-/g, " ");
    const data = WORD_DATA[key];
    if (!data) {
        const fuzzy = Object.keys(WORD_DATA).find(k => k.includes(key) || key.includes(k));
        if (!fuzzy)
            return empty;
        const d = WORD_DATA[fuzzy];
        return { word: fuzzy, synonyms: d.syn, antonyms: d.ant, source: "local-thesaurus" };
    }
    return { word: key, synonyms: data.syn, antonyms: data.ant, source: "local-thesaurus" };
}
export async function lookupWord(word) {
    const [definitions, thesaurus] = await Promise.all([
        lookupDictionary(word),
        lookupThesaurus(word),
    ]);
    const relatedWords = [...new Set([...thesaurus.synonyms, ...thesaurus.antonyms])];
    return {
        word,
        definitions,
        synonyms: thesaurus.synonyms,
        antonyms: thesaurus.antonyms,
        relatedWords,
    };
}
export async function searchImages(query, count = 5) {
    const results = [];
    const words = query.toLowerCase().split(/\s+/).filter(Boolean);
    const hueFromString = (s) => {
        let h = 0;
        for (let i = 0; i < s.length; i++)
            h = ((h << 5) - h + s.charCodeAt(i)) | 0;
        return Math.abs(h) % 360;
    };
    for (let i = 0; i < count; i++) {
        const seed = `${query}_${i}`;
        const hue = hueFromString(seed);
        const title = `${words.slice(0, 3).join(" ")} (${i + 1})`;
        const svg = `data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256">` +
            `<rect width="256" height="256" fill="hsl(${hue},60%,20%)"/>` +
            `<circle cx="128" cy="100" r="50" fill="hsl(${(hue + 60) % 360},70%,50%)" opacity="0.7"/>` +
            `<rect x="64" y="160" width="128" height="60" rx="8" fill="hsl(${(hue + 120) % 360},60%,40%)" opacity="0.6"/>` +
            `<text x="128" y="240" text-anchor="middle" fill="white" font-size="12" font-family="sans-serif">${title}</text>` +
            `</svg>`)}`;
        results.push({ url: svg, title, source: "neuroclaw-local" });
    }
    return results;
}
